if (znEntry) {
  result = znEntry.zn;
} else {
  const zhHkEntry = altTitles.find(item => 'zh-hk' in item);
  if (zhHkEntry) {
    result = zhHkEntry['zh-hk'];
  } else {
    const originalEntry = altTitles.find(item => originalLang in item);
    result = originalEntry?.[originalLang] || list.attributes.title.en;
  }
}
result.split('\n')[0];

